  assert.equal(r.ok, true);
  assert.equal(r.value, 0);
});

test('convert with negative amount', () => {
  const r = convert(-10000, 'USD');
  assert.equal(r.ok, true);
  assert.equal(r.value, -10850);
});

test('convert handles rounding correctly', () => {
  const r = convert(1, 'USD');
  // 1 cent EUR = 0.01 EUR
  // 0.01 EUR × 1.085 = 0.01085 USD = 1.085 cents USD
  // Rounded: 1 cent USD
  assert.equal(r.ok, true);
  assert.equal(r.value, 1);
});

test('convert with 3-digit amount', () => {
  const r = convert(12345, 'USD');
  // 12345 cents EUR = 123.45 EUR
  // 123.45 EUR × 1.085 = 133.94325 USD = 13394.325 cents USD
  assert.equal(r.ok, true);
  assert.equal(r.value, 13394);
});

test('convert GBP with decimal result', () => {
  const r = convert(12345, 'GBP');
  // 12345 cents EUR = 123.45 EUR
  // 123.45 EUR × 0.8425 = 104.006625 GBP = 10400.6625 cents GBP → 10401 rounded
  assert.equal(r.ok, true);
  assert.equal(r.value, 10401);
});

test('formatMoney EUR formats with euro sign', () => {
  const r = formatMoney(123456, 'EUR');
  assert.equal(r.ok, true);
  assert.equal(r.value, '€1,234.56');
});

test('formatMoney USD formats with dollar sign', () => {
  const r = formatMoney(10000, 'USD');
  assert.equal(r.ok, true);
  assert.equal(r.value, '$108.50');
});

test('formatMoney GBP formats with pound sign', () => {
  const r = formatMoney(10000, 'GBP');
  assert.equal(r.ok, true);
  assert.equal(r.value, '£84.25');
});

test('formatMoney USD with thousands separator', () => {
  const r = formatMoney(1234567, 'USD');
  assert.equal(r.ok, true);
  assert.ok(r.value.includes(','));
  // 1234567 cents EUR = 12345.67 EUR × 1.085 = 13394.65195 USD
  assert.equal(r.value, '$13,394.65');
});

test('formatMoney with small amount', () => {
  const r = formatMoney(5, 'EUR');
  assert.equal(r.ok, true);
  assert.equal(r.value, '€0.05');
});

test('formatMoney with negative amount EUR', () => {
  const r = formatMoney(-250, 'EUR');
  assert.equal(r.ok, true);
  assert.equal(r.value, '-€2.50');
});

test('formatMoney with negative amount USD', () => {
  const r = formatMoney(-10000, 'USD');
  assert.equal(r.ok, true);
  assert.equal(r.value, '-$108.50');
});

test('formatMoney rejects unknown currency', () => {
  const r = formatMoney(10000, 'XXX');
  assert.deepEqual(r, { ok: false, error: 'UNKNOWN_CURRENCY' });
});

test('formatMoney with zero', () => {
  const r = formatMoney(0, 'USD');
  assert.equal(r.ok, true);
  assert.equal(r.value, '$0.00');
});

test('formatMoney large EUR amount', () => {
  const r = formatMoney(100000000, 'EUR');
  assert.equal(r.ok, true);
  assert.equal(r.value, '€1,000,000.00');
});

test('formatMoney GBP with large amount', () => {
  const r = formatMoney(100000000, 'GBP');
  assert.equal(r.ok, true);
  // 100000000 cents EUR = 1000000 EUR
  // 1000000 EUR × 0.8425 = 842500 GBP = 84250000 cents GBP
  assert.equal(r.value, '£842,500.00');
});

test('convert and formatMoney are consistent', () => {
  const cents = 123456;
  const convertResult = convert(cents, 'USD');
  const formatResult = formatMoney(cents, 'USD');

  assert.equal(convertResult.ok, true);
  assert.equal(formatResult.ok, true);

  // Extract the numeric value from formatted string
  const formattedAmount = formatResult.value.replace(/[$,]/g, '');
  const expectedAmount = (convertResult.value / 100).toFixed(2);
  assert.equal(formattedAmount, expectedAmount);
});

test('formatMoney does not mutate input', () => {
  const amount = 12345;
  formatMoney(amount, 'USD');
  assert.equal(amount, 12345);
});

test('convert multiple currencies consistently', () => {
  const eur = 10000;
  const usd = convert(eur, 'USD');
  const gbp = convert(eur, 'GBP');

  assert.equal(usd.ok, true);
  assert.equal(gbp.ok, true);
  assert.ok(usd.value > eur); // USD is stronger
  assert.ok(gbp.value < eur); // GBP is weaker
});

test('formatMoney with precise decimal conversion', () => {
  const r = formatMoney(33, 'USD');
  // 33 cents EUR = 0.33 EUR
  // 0.33 EUR × 1.085 = 0.35805 USD = 35.805 cents USD → 36 rounded
  assert.equal(r.ok, true);
  // Should be 36 cents = $0.36
  assert.equal(r.value, '$0.36');
});
